  'В пропуске теперь каждый сезон свои облики: бесплатный — эпический, золотой — легендарный с короной и крыльями.': 'Every pass season now has its own outfits: the free one is epic, the gold one is legendary with a crown and wings.',
  'Праздничные облики стали разными: у каждого праздника и года свой металл, цвета и узор.': 'Holiday outfits now differ: each holiday and year has its own metal, colors and pattern.',
  'Нажми на награду в пропуске — откроется её обзор, облик видно в 3D.': 'Tap a pass reward to open its overview, outfits are shown in 3D.',
  'Примерка в лавке': 'Try-on in the shop',
  'В лавке у каждого облика теперь 3D-портрет героя вместо цветного квадрата.': 'Every outfit in the shop now shows a 3D portrait of the hero instead of a colored square.',
  'Нажми на облик — герой в нём крутится на подставке, видно все детали ещё до покупки.': 'Tap an outfit to see the hero wearing it on a turntable, with every detail visible before you buy.',
