  'График': 'Chart',
  'Добро пожаловать в NikitenokArena!': 'Welcome to NikitenokArena!',
  'Я Мастер Гром. Князь Диван усыпил королевство Атлетию ленью, и разбудить его можно только движением. Здесь каждый твой повтор — удар по врагу, шаг по карте и сила героя.': 'I\'m Master Thunder. Prince Couch has put the kingdom of Athletia to sleep with laziness, and only movement can wake it up. Here every rep is a hit on an enemy, a step on the map and strength for your hero.',
  'Камера считает сама': 'The camera counts for you',
  'Поставь телефон сбоку на уровне пояса, чтобы в кадр попадало всё тело. Видео никуда не уходит: распознавание работает прямо на телефоне.': 'Place your phone to the side at waist height so your whole body is in the frame. Video never leaves your phone: recognition runs right on the device.',
  'Четыре раздела': 'Four sections',
  '— твой уровень, снаряжение и задание дня от жителей.': '— your level, gear and the villagers\' daily quest.',
  '— 300 уровней в трёх мирах, боссы и сундуки.': '— 300 levels across worlds, bosses and chests.',
  '— друзья, чат и рейд-босс по выходным.': '— friends, chat and a raid boss on weekends.',
  '— бой с живым соперником: кто больше повторов.': '— a fight with a real opponent: whoever does more reps wins.',
  'Начнём с испытания': 'Let\'s start with a trial',
  'Минута приседаний, сколько сможешь. Так я пойму твою форму и подберу врагов по силе: дальше они будут расти вместе с тобой.': 'One minute of squats, as many as you can. This shows me your fitness so I can match enemies to your strength: they\'ll grow along with you.',
