  'Битва городов — для тех, кто вошёл через Telegram, Max или Яндекс. Войди в настройках, и твои повторы зажгут твой город.': 'City Battle is for players signed in via Telegram, Max or Yandex. Sign in in settings and your reps will light up your city.',
