  'Что не так? Жалобу увидит модератор, автор не узнает, кто пожаловался.': 'What\'s wrong? A moderator will see the report; the author won\'t know who reported.',
  'Его сообщения в чате пропадут для тебя, а позвать тебя в друзья или на дуэль он не сможет. Если вы друзья, дружба удалится. Снять блок можно в настройках, в «Чёрном списке».': 'Their chat messages will disappear for you, and they won\'t be able to add you as a friend or challenge you to a duel. If you\'re friends, the friendship will be removed. You can unblock them in settings, in the “Block list”.',
  'Заблокировать {0}': 'Block {0}',
  'Чёрный список': 'Block list',
  'Игроки, чьи сообщения ты не видишь. Они не могут звать тебя в друзья и на дуэль.': 'Players whose messages you don\'t see. They can\'t add you as a friend or challenge you to a duel.',
