  'Загружаю…': 'Loading…',
  'Чёрный список работает, когда игра открыта из Telegram': 'The block list works when the game is opened from Telegram',
  'Здесь пусто. Заблокировать игрока можно, нажав на его сообщение в чате клана или на него в списке друзей.': 'Nothing here. You can block a player by tapping their message in the clan chat or their name in your friends list.',
