  'Аккаунт': 'Account',
  'Сейчас ты играешь гостем: без рейтинга и клана, прогресс только в этом браузере. Войди, и герой станет общим с Telegram и Max.': 'You\'re playing as a guest: no ranking or clan, progress only in this browser. Sign in and your hero will be shared with Telegram and Max.',
