  'Привязать': 'Link',
  'Герой есть и здесь, и там. Объединить их нельзя: выбери, кем играть дальше. Второй уйдёт в архив: его можно вернуть в «Настройки» → «Аккаунт» в течение 30 дней.': 'You have a hero both here and there. They can\'t be merged: choose which one to keep playing. The other goes to the archive: you can restore it in “Settings” → “Account” within 30 days.',
