  'Внучек, помоги натаскать воды из колодца: каждое приседание — полное ведро.': 'Dear, help me fetch water from the well: every squat is a full bucket.',
  'Тесто на пироги сегодня тугое, без крепких рук не замесить.': 'The pie dough is stiff today, can\'t knead it without strong arms.',
  'Кузнице нужны сильные руки. Покажи, что мои уроки не прошли даром.': 'The forge needs strong arms. Show me my lessons weren\'t in vain.',
  'Ноги — опора бойца. Сегодня тренируем их так, чтобы гора дрожала.': 'Legs are a fighter\'s foundation. Today we train them until the mountain shakes.',
  'Крепкий живот держит удар. Пресс сегодня — главное оружие.': 'A strong core takes a hit. Abs are today\'s main weapon.',
  'Тренирую ловкость перед вылазкой. Составишь компанию? Кто больше раз на пресс!': 'Training my agility before a raid. Join me? Whoever does more sit-ups!',
  'Прыжки по крышам начинаются с приседаний. Не отставай!': 'Rooftop jumps start with squats. Keep up!',
  'Обоз с товаром застрял. Подтолкнёшь? Монет не пожалею.': 'My cart got stuck. Give it a push? I\'ll pay well.',
  'Мешки с зерном сами себя не поднимут. Заплачу по-купечески.': 'Grain sacks won\'t lift themselves. I\'ll pay like a merchant.',
  'Помнишь, как я сам начинал с десятка отжиманий? Давай вместе, на совесть.': 'Remember how I started with ten push-ups? Let\'s do it together, properly.',
  'Спина после огорода гудит, а пресс её бережёт. Покачаемся?': 'My back aches after the garden, and abs protect it. Shall we work out?',
  'БИП! Батареи корабля пусты. Генератор крутится от приседаний. БИП-БИП!': 'BEEP! The ship\'s batteries are empty. The generator runs on squats. BEEP-BEEP!',
  'Пилоту нужны стальные руки на штурвале. Это приказ, кадет!': 'A pilot needs steel arms on the controls. That\'s an order, cadet!',
  'Перегрузки при взлёте держит пресс. Тренировка экипажа начинается.': 'Abs handle the G-forces at takeoff. Crew training begins.',
  'Боец, который стоит как скала, не падает от удара. Постой в планке, пока я считаю.': 'A fighter who stands like a rock doesn\'t fall from a hit. Hold a plank while I count.',
  'Невесомость не прощает слабого корпуса. Держим планку, кадет, по секундомеру!': 'Zero gravity doesn\'t forgive a weak core. Hold the plank, cadet, on the stopwatch!',
