  'Выполни 50 заданий дня': 'Complete 50 daily quests',
  'Рейдер': 'Raider',
  'Получи награду клана за рейд-босса': 'Get a clan reward for a raid boss',
  'Ветеран рейдов': 'Raid Veteran',
  '10 наград за рейды': '10 raid rewards',
  'Легенда арсенала': 'Arsenal Legend',
  'Добудь легендарную вещь': 'Get a legendary item',
  'Минута в планке за один подход': 'A minute of plank in one set',
  'Скала': 'The Rock',
  'Три минуты в планке за один подход': 'Three minutes of plank in one set',
  'Спелеолог': 'Spelunker',
  'Пройди 10 этажей подземелья': 'Clear 10 dungeon floors',
  'Гроза подземелий': 'Terror of Dungeons',
  'Победи трёх хранителей подземелья': 'Defeat three dungeon guardians',
  'Цепная реакция': 'Chain Reaction',
  'Комбо ×6 в подземелье': 'Combo ×6 in the dungeon',
  'Пройди программу «{0}»': 'Complete the “{0}” program',
  'Собери коллекцию «{0}»': 'Complete the “{0}” collection',
  'Пройди дорожку праздника «{0}» {1}': 'Complete the “{0}” {1} festival track',
  'Новичок: 14 дней в форму': 'Beginner: 14 Days to Fit',
  'Все упражнения понемногу, без перегрузки': 'A bit of every exercise, no overload',
  'Две недели, и тело вспомнит, что такое сила. Каждый день — короткий круг: приседания, отжимания, пресс и планка. Не геройствуй, главное — не пропускать.': 'Two weeks, and your body will remember what strength is. Every day — a short circuit: squats, push-ups, sit-ups and plank. Don\'t overdo it, the key is not to skip.',
  '100 отжиманий за 30 дней': '100 Push-ups in 30 Days',
  'Сотня за тренировку к последнему дню': 'A hundred per workout by the last day',
  'Через месяц ты сделаешь сто отжиманий за одну тренировку. Пять подходов каждый день, отдых каждый третий. В первый день узнаем, с чего начинаешь.': 'In a month you\'ll do a hundred push-ups in one workout. Five sets every day, rest every third day. On day one we\'ll find your starting point.',
  'Стальной пресс 21 день': 'Steel Core in 21 Days',
  'Пресс и планка: корпус как броня': 'Sit-ups and plank: a core like armor',
  'Три недели работы над корпусом. Скручивания на пресс и планка каждый день, отдых каждый четвёртый. В финале сравним с первым днём.': 'Three weeks of core work. Sit-ups and plank every day, rest every fourth day. At the end we\'ll compare with day one.',
  'Ноги богатыря 28 дней': 'Bogatyr Legs in 28 Days',
  'Приседания до дрожи в земле': 'Squats until the ground shakes',
  'Ноги держат бойца. Четыре недели приседаний: пять подходов, нагрузка растёт до полуторных твоих. Отдых каждый четвёртый день, без него мышцы не растут.': 'Legs carry a fighter. Four weeks of squats: five sets, the load grows to one and a half times yours. Rest every fourth day — muscles don\'t grow without it.',
  'Планка 5 минут за 30 дней': '5-Minute Plank in 30 Days',
  'От первых секунд до пяти минут': 'From the first seconds to five minutes',
  'Пять минут в планке — это характер. Каждый день держим чуть дольше, отдых каждый пятый день. Таз ровно, локти под плечами, я слежу за секундами.': 'Five minutes in a plank is character. Every day we hold a bit longer, rest every fifth day. Hips level, elbows under shoulders, I\'m watching the seconds.',
  'Полное тело 4 недели': 'Full Body in 4 Weeks',
  'Три круга по всему телу': 'Three full-body circuits',
  'Четыре недели, как у настоящих бойцов: три круга по всему телу, нагрузка растёт каждую неделю. Пройдёшь — сделаю тебе доспех чемпиона.': 'Four weeks like real fighters: three full-body circuits, the load grows every week. Finish it and I\'ll make you a champion\'s armor.',
  'Входной тест': 'Entry test',
  'Легенда Атлетии': 'Legend of Athletia',
