  'подход': 'set',
  'подхода': 'sets',
  'подходов': 'sets',
  'Пехота с мечом и щитом. Идёт к ближайшей постройке и рубит её, а стену на пути ломает. Дешёвый и быстро обучается — силён толпой.': 'Infantry with a sword and shield. Goes to the nearest building and hacks at it, breaking walls in the way. Cheap and quick to train — strong in numbers.',
  'Стрелок с арбалетом. Бьёт издалека, поэтому достаёт постройки даже из-за стен. Здоровья мало — пускай вперёд воинов или великанов.': 'A crossbow shooter. Strikes from afar, so it reaches buildings even behind walls. Low health — send warriors or giants ahead.',
  'Здоровяк с двуручным топором. Не отвлекается на прочие постройки: идёт прямо к башням и катапультам и принимает их удары на себя.': 'A big guy with a two-handed axe. Ignores other buildings: heads straight for towers and catapults and takes their hits.',
  'Скелет с бомбой. Бежит к ближайшей стене и взрывается вместе с ней — задевает всё вокруг. Погибает при взрыве.': 'A skeleton with a bomb. Runs to the nearest wall and blows up with it — hitting everything around. Dies in the blast.',
  'Летит над стенами и лечит отряды рядом с собой, сначала раненых. Сам не атакует. Береги от башен лучников.': 'Flies over walls and heals nearby troops, the wounded first. Doesn\'t attack. Keep it away from archer towers.',
  'Любые постройки — ближайшие': 'Any buildings — the nearest',
  'Оборона: башни и катапульты': 'Defenses: towers and catapults',
  'Стены, потом любые постройки': 'Walls, then any buildings',
  'Свои отряды — сначала раненые': 'Own troops — the wounded first',
  'очень быстро': 'very fast',
  'быстро': 'fast',
