  'Внучок, без дров зиму не пережить. Поставь лесопилку!': 'Dear, we won\'t survive winter without firewood. Build a lumber mill!',
  'Стены сами себя не сложат. Нужна каменоломня.': 'Walls won\'t build themselves. We need a quarry.',
  'Золото любит счёт. Построй рудник — буду торговать.': 'Gold loves to be counted. Build a mine — I\'ll trade.',
  'Без казарм нет войска. А без войска лентяев не прогнать!': 'No barracks, no army. And without an army we can\'t drive off the slackers!',
  'Князь Диван уже присматривается. Поставь башню лучников.': 'Prince Couch is already eyeing us. Build an archer tower.',
  'Обучи пятерых воинов — покажем, кто тут не ленится.': 'Train five warriors — we\'ll show who\'s not lazy around here.',
  'Я выследила заставу лентяев. Разгроми её!': 'I tracked down a slacker outpost. Destroy it!',
  'Ратуша тесновата. Улучши её до второго уровня.': 'The town hall is cramped. Upgrade it to level two.',
  'Построй кузницу: острый меч — меньше лишних повторов.': 'Build a forge: a sharp sword means fewer extra reps.',
  'БИП! Построй лабораторию: я прокачаю отряды. Каждый твой повтор ускорит исследование.': 'BEEP! Build a lab: I\'ll upgrade the troops. Every rep speeds up research.',
  'Обнеси деревню стеной — хотя бы десять секций.': 'Wall in the village — at least ten sections.',
  'Одной башни мало. Поставь вторую.': 'One tower isn\'t enough. Build a second.',
  'Три лагеря Князя — и он задумается!': 'Three of the Prince\'s camps — and he\'ll think twice!',
  'Ратуша третьего уровня откроет таверну и катапульты.': 'A level three town hall unlocks the tavern and catapults.',
  'Таверна! Где ещё герою отдохнуть после тренировки?': 'A tavern! Where else can a hero rest after a workout?',
  'БИП-7 рассчитал: катапульта повышает защиту на 37%.': 'BEEP-7 calculated: a catapult raises defense by 37%.',
  'Отбей набег лентяев — пусть уйдут без звёзд.': 'Repel a slacker raid — let them leave without stars.',
  'Пять лагерей позади — Князь в панике!': 'Five camps down — the Prince is panicking!',
  'Ратуша четвёртого уровня: третий строитель и рынок.': 'Level four town hall: a third builder and the market.',
  'Рынок — и монеты за победы потекут рекой.': 'A market — and coins for victories will flow like a river.',
