  'Сердце деревни. Её уровень открывает новые постройки и уровни.': 'The heart of the village. Its level unlocks new buildings and levels.',
  'Лесопилка': 'Lumber mill',
  'Сама пилит дерево, пока ты тренируешься.': 'Saws wood by itself while you train.',
  'Каменоломня': 'Quarry',
  'Добывает камень для стен и построек.': 'Mines stone for walls and buildings.',
  'Золотой рудник': 'Gold mine',
  'Понемногу намывает золото на войско.': 'Slowly pans gold for the army.',
  'Склад': 'Storage',
  'Вмещает урожай сборщиков и прячет четверть запасов от набегов.': 'Holds the collectors\' harvest and hides a quarter of resources from raids.',
  'Обучают войско. Уровень открывает новые отряды, усиливает их и даёт больше мест.': 'Trains the army. Its level unlocks new troops, makes them stronger and adds space.',
  'Здесь прокачивают отряды: каждый уровень отряда — +15% здоровья и урона. Повторы на тренировке ускоряют исследование.': 'Troops are upgraded here: each troop level gives +15% health and damage. Workout reps speed up research.',
  'Кузница': 'Forge',
  'Точит оружие героя: +1% урона в походах за каждый уровень.': 'Sharpens the hero\'s weapon: +1% quest damage per level.',
  'Таверна': 'Tavern',
  'Здесь герой отдыхает: +1 жизнь, с 5 уровня — +2.': 'The hero rests here: +1 life, +2 from level 5.',
  'Рынок': 'Market',
  'Купцы платят щедрее: +2% монет за победы за каждый уровень.': 'Merchants pay more: +2% coins for victories per level.',
