  'Стреляет по ближайшему врагу.': 'Shoots the nearest enemy.',
  'Катапульта': 'Catapult',
  'Медленно, но больно бьёт по толпе. Вблизи не достаёт.': 'Slow but hits crowds hard. Can\'t reach up close.',
  'Стена': 'Wall',
  'Задерживает врагов: им придётся ломать или обходить.': 'Holds enemies back: they have to break it or go around.',
  'Скрытая бомба': 'Hidden bomb',
  'Прячется в траве и взрывается под ногами у толпы. Нападающий её не видит.': 'Hides in the grass and explodes under a crowd. The attacker can\'t see it.',
  'Капкан': 'Snare',
  'Хватает первого, кто наступит, и держит на месте. Даже великана.': 'Grabs the first one to step on it and holds them in place. Even a giant.',
