  'Лаборатория уже занята исследованием.': 'The lab is already busy with research.',
  'Лабораторию сейчас улучшают.': 'The lab is being upgraded right now.',
  'Отряд ещё не открыт в казармах.': 'The troop isn\'t unlocked in the barracks yet.',
  'Отряд уже самого высокого уровня.': 'The troop is already at the highest level.',
  'Нужна лаборатория выше уровнем.': 'Higher-level lab required.',
  'Застава лентяев': 'Slacker Outpost',
  'Одна башня — высаживай воинов с другой стороны.': 'One tower — deploy warriors on the other side.',
  'Диванный хутор': 'Couch Farmstead',
  'Две башни прикрывают друг друга. Бей с угла.': 'Two towers cover each other. Attack from a corner.',
  'Подушечный острог': 'Pillow Stockade',
  'Ратуша за стеной: воины её проломят, лучники стреляют поверх.': 'The town hall is behind a wall: warriors will break through, archers shoot over it.',
  'Крепость Зевоты': 'Fortress of Yawns',
  'Катапульта бьёт по толпе — не высаживай всех в одно место. И берегись спрятанной бомбы.': 'The catapult hits crowds — don\'t deploy everyone in one spot. And watch out for the hidden bomb.',
  'Сонная цитадель': 'Sleepy Citadel',
  'Великаны примут удар башен на себя.': 'Giants will tank the towers\' hits.',
  'Бастион Пледа': 'Blanket Bastion',
  'Подрывники откроют путь к ратуше.': 'Wall breakers will open the way to the town hall.',
  'Твердыня Прокрастинации': 'Stronghold of Procrastination',
  'Целитель за великанами — и стены не помеха. У ратуши дежурит страж Князя.': 'A healer behind giants — and walls are no obstacle. The Prince\'s guard is on duty at the town hall.',
  'Диванный дворец': 'Couch Palace',
  'Логово самого Князя: он сам охраняет ратушу. Приходи с полным лагерем.': 'The lair of the Prince himself: he guards the town hall personally. Come with a full camp.',
  'Оскорбления': 'Insults',
