  'Мат': 'Profanity',
  'Другое': 'Other',
  'Ты не можешь писать в чат до решения модератора': 'You can\'t write in the chat until a moderator decides',
  'Ты не можешь писать в чат до {0}.{1} в {2}:{3} (мск)': 'You can\'t write in the chat until {0}.{1} at {2}:{3} (Moscow time)',
  'Великан Лень': 'Giant Sloth',
  'Спит на горе одеял и тянет силы из всего королевства': 'Sleeps on a mountain of blankets and drains strength from the whole kingdom',
  'Король Прокрастин': 'King Procrastin',
