  'Оплата пришла, но мы не поняли, за что. Разработчик уже знает и разберётся.': 'The payment arrived, but we couldn\'t tell what it was for. The developer already knows and will sort it out.',
  'Ярлык игры уже на главном экране телефона.': 'The game shortcut is already on your home screen.',
  '📲 Ярлык на главный экран': '📲 Add to home screen',
  'Открывай игру в один тап — прямо с главного экрана телефона.': 'Open the game in one tap — right from your phone\'s home screen.',
  '📲 Добавить ярлык': '📲 Add shortcut',
  'Значок «{0}» теперь у твоего имени в Telegram': 'The “{0}” badge is now next to your name in Telegram',
