  "Лента и профили игроков": "Feed and player profiles",
  "На главной — «Лента»: выложи фото и пару слов о тренировке, а через год сравни, как изменился.": "New «Feed» on the home screen: post a photo and a few words about your workout, then compare a year later.",
  "Ставь 💪 респект чужим постам и подписывайся на тех, кто вдохновляет: о новых постах напомнит бот.": "Give 💪 respect to posts and follow players who inspire you: the bot will tell you about their new posts.",
  "Нажми на игрока в рейтинге, ленте, клане или у друзей — откроется профиль: рекорды, что получается лучше всего, когда был в игре.": "Tap a player in a leaderboard, the feed, your clan or friends to open their profile: records, what they're best at, when they last played.",
  "Из профиля можно позвать в друзья, подписаться или пожаловаться.": "From a profile you can add a friend, follow or report.",
  "Разминка": "Warm-up",
  "Перед первым подходом за день Гром предложит размяться пару минут. Можно пропустить.": "Before your first set of the day, Grom offers a quick two-minute warm-up. You can skip it.",
  "Подсказки, разминка, скелет, калибровка": "Tips, warm-up, skeleton, calibration",
