  "Герой показывает каждое движение в 3D, рядом таймер. Можно поставить на паузу или пропустить.": "Your hero shows every move in 3D next to a timer. You can pause or skip.",
  "Отключить можно в настройках, раздел «Камера и тренировки».": "You can turn it off in Settings → Camera & training.",
  "Сначала разминка?": "Warm up first?",
  "Первый подход за день. {0} минуты — суставы и мышцы разогреются, повторы пойдут легче, а риск травмы меньше.": "Your first set today. {0} minutes to warm up your joints and muscles: reps get easier and injuries less likely.",
