  "Отжимания, приседания и пресс с камерой — в Telegram": "Push-ups, squats and sit-ups counted by camera, in Telegram",
  "Клан и «Поделиться» в ленте": "Clans and sharing in the feed",
  "В профиле игрока нажми на его клан: увидишь карточку клана и сможешь вступить.": "Tap a player's clan in their profile to see the clan card and join.",
  "Любым постом можно поделиться: в сторис Telegram, в чат или картинкой. На картинке — ссылка, которая откроет этот пост в игре.": "Share any post to Telegram stories, a chat or as an image. The image links straight to the post in the game.",
  "Утренняя зарядка": "Morning exercise",
  "Утром при первом заходе предложим начать день с короткой зарядки.": "On your first morning visit we'll offer to start the day with a short workout.",
  "Зарядка сделана: {0} повторов уже в счёт дня. Хорошего дня, боец!": "Morning workout done: {0} reps already count for today. Have a great day, fighter!",
  "С добрым утром!": "Good morning!",
