  "Зарядка сделана. Хорошего дня!": "Workout done. Have a great day!",
  "Доброе утро! Начнём день с зарядки?": "Good morning! Start the day with a quick workout?",
  "Пара минут: разомнёмся, потом {0} приседаний и {1} отжиманий. Бодрость на весь день.": "A couple of minutes: a warm-up, then {0} squats and {1} push-ups. Energy for the whole day.",
