  "Бодрое начало дня": "An energetic start",
  "{0} приседаний": "{0} squats",
  "Спина прямая, пятки на полу, садись до параллели бёдер с полом.": "Back straight, heels down, squat until your thighs are parallel to the floor.",
  "{0} отжиманий": "{0} push-ups",
  "Тело — ровная линия. Тяжело — отжимайся с колен.": "Keep your body in a straight line. Too hard? Do them from your knees.",
  "Утренняя зарядка по утрам": "Morning exercise",
  "Фото игроков в ленте": "Player photos in the feed",
  "В ленте, профилях и на картинке поста теперь видно фото из профиля Telegram, а не только первую букву имени.": "The feed, profiles and post images now show the Telegram profile photo instead of just the first letter of the name.",
  "Если фото скрыто настройками приватности Telegram, остаётся буква.": "If the photo is hidden by Telegram privacy settings, the letter stays.",
  "Утром при первом заходе Гром предлагает начать день с зарядки: немного разминки, приседания и отжимания.": "On your first morning visit Grom offers to start the day with a short workout: a warm-up, squats and push-ups.",
  "С камерой повторы идут в счёт дня, без камеры герой просто показывает, как делать.": "With the camera your reps count for the day; without it your hero just shows how to do them.",
  "Не нравится — нажми «Не показывать больше» или выключи в настройках.": "Not for you? Tap «Don't show again» or turn it off in Settings.",
  "Рассказывать о победах в ленте": "Post my wins to the feed",
  "Игра сама выложит в ленту победу над боссом, серию тренировок, новый уровень героя и выигранный вызов в чате.": "The game posts to the feed when you beat a boss, reach a training streak, level up your hero or win a chat challenge.",
