  "Облик «{0}» твой!": "The «{0}» outfit is yours!",
  "И ещё +{0} монет. Спасибо, что с нами — в канале советы, новости игры и челленджи.": "Plus +{0} coins. Thanks for joining — the channel has tips, game news and challenges.",
  "Подпишись на канал игры — облик «{0}»": "Subscribe to the game channel — get the «{0}» outfit",
  "Пока не видим подписку. Подпишись в канале и нажми «Забрать» ещё раз.": "We don't see your subscription yet. Subscribe in the channel and tap «Claim» again.",
  "Эпический облик и +{0} монет. В канале — советы, новости игры и челленджи.": "An epic outfit and +{0} coins. The channel has tips, game news and challenges.",
