  "📣 В ленту": "📣 Post to feed",
  "Лента оживает": "The feed comes alive",
  "Мастер Гром каждое утро подводит итоги вчерашнего дня на Арене, днём персонажи дают советы, а вечером Лиса бросает вызов.": "Every morning Master Grom sums up yesterday at the Arena, characters share tips during the day, and in the evening Lisa throws down a challenge.",
  "Победа над боссом, серия тренировок и новый уровень героя сами появляются в ленте. Выключить — в настройках, раздел «Уведомления».": "Boss wins, training streaks and new hero levels now appear in the feed automatically. Turn it off in Settings → Notifications.",
  "После победы — кнопка «В ленту»: готовая карточка с уровнем, звёздами и повторами.": "After a win, tap «Post to feed» for a ready card with the level, stars and reps.",
  "Подпишись на канал игры — получишь облик «Вестник Арены» и монеты.": "Subscribe to the game channel to get the «Arena Herald» outfit and coins.",
